const listShopOrders = `-- name: ListShopOrders :many
SELECT o.id FROM orders o
WHERE o.shop_id = ANY($1::uuid[])
  -- Le marchand ne voit que les commandes payées.
  AND o.paid_at IS NOT NULL
  AND ($2::text IS NULL OR o.status = $2::text)
  -- Groupe d'onglet (nouvelles, en cours, terminées) : liste de statuts, NULL pour toutes.
  AND ($3::text[] IS NULL OR o.status = ANY($3::text[]))
ORDER BY o.created_at DESC
LIMIT $5 OFFSET $4
`

type ListShopOrdersParams struct {
	ShopIds  []uuid.UUID
	Status   *string
	Statuses []string
	Off      int32
	Lim      int32
}

func (q *Queries) ListShopOrders(ctx context.Context, arg ListShopOrdersParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listShopOrders,
		arg.ShopIds,
		arg.Status,
		arg.Statuses,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockOrder = `-- name: LockOrder :one
SELECT status FROM orders WHERE id = $1 FOR UPDATE
`

func (q *Queries) LockOrder(ctx context.Context, id uuid.UUID) (string, error) {
	row := q.db.QueryRow(ctx, lockOrder, id)
	var status string
	err := row.Scan(&status)
	return status, err
}

const metrics = `-- name: Metrics :one
SELECT
  count(*) FILTER (WHERE paid_at IS NOT NULL)::bigint AS paid_orders,
  count(*) FILTER (WHERE status IN ('completed', 'delivered'))::bigint AS completed_orders,
  count(*) FILTER (WHERE paid_at IS NOT NULL AND status IN ('cancelled', 'refunded', 'returned_to_shop'))::bigint AS cancelled_after_payment,
  count(*) FILTER (WHERE status = 'expired')::bigint AS expired_orders,
  coalesce(sum(total_xof) FILTER (WHERE status IN ('completed', 'delivered')), 0)::bigint AS gmv_xof,
  coalesce(sum(commission_xof) FILTER (WHERE status IN ('completed', 'delivered')), 0)::bigint AS commission_xof,
  coalesce(percentile_cont(0.5) WITHIN GROUP (ORDER BY extract(epoch FROM completed_at - ready_at))
    FILTER (WHERE status = 'delivered' AND ready_at IS NOT NULL), 0)::float8 AS median_ready_to_delivered_s
FROM orders
WHERE created_at >= $1::timestamptz AND created_at < $2::timestamptz
`

type MetricsParams struct {
	FromTime time.Time
	ToTime   time.Time
}

type MetricsRow struct {
	PaidOrders              int64
	CompletedOrders         int64
	CancelledAfterPayment   int64
	ExpiredOrders           int64
	GmvXof                  int64
	CommissionXof           int64
	MedianReadyToDeliveredS float64
}

func (q *Queries) Metrics(ctx context.Context, arg MetricsParams) (MetricsRow, error) {
	row := q.db.QueryRow(ctx, metrics, arg.FromTime, arg.ToTime)
	var i MetricsRow
	err := row.Scan(
		&i.PaidOrders,
		&i.CompletedOrders,
		&i.CancelledAfterPayment,
		&i.ExpiredOrders,
		&i.GmvXof,
		&i.CommissionXof,
		&i.MedianReadyToDeliveredS,
	)
	return i, err
}

const overviewCounts = `-- name: OverviewCounts :one
SELECT
  count(*) FILTER (WHERE status IN ('awaiting_seller', 'accepted', 'preparing', 'ready_for_pickup',
                                    'awaiting_driver', 'driver_assigned', 'picked_up'))::bigint AS active,
  count(*) FILTER (WHERE status = 'awaiting_seller')::bigint AS to_accept,
  count(*) FILTER (WHERE status = 'awaiting_driver')::bigint AS without_driver,
  count(*) FILTER (WHERE handover_attempts >= 5
                     AND status IN ('ready_for_pickup', 'driver_assigned', 'picked_up'))::bigint AS handover_locked,
  count(*) FILTER (WHERE status IN ('cancelled', 'returned_to_shop') AND refund_due_xof > 0)::bigint AS refunds,
  coalesce(sum(refund_due_xof) FILTER (WHERE status IN ('cancelled', 'returned_to_shop') AND refund_due_xof > 0), 0)::bigint AS refunds_xof
FROM orders
`

type OverviewCountsRow struct {
	Active         int64
	ToAccept       int64
	WithoutDriver  int64
	HandoverLocked int64
	Refunds        int64
	RefundsXof     int64
}

// Compteurs du tableau de bord : commandes en cours et leurs groupes, codes bloqués, file de
// remboursement (même définition que RefundQueue).
func (q *Queries) OverviewCounts(ctx context.Context) (OverviewCountsRow, error) {
	row := q.db.QueryRow(ctx, overviewCounts)
	var i OverviewCountsRow
	err := row.Scan(
		&i.Active,
		&i.ToAccept,
		&i.WithoutDriver,
		&i.HandoverLocked,
		&i.Refunds,
		&i.RefundsXof,
	)
	return i, err
}

