const updateStatus = `-- name: UpdateStatus :execrows
UPDATE orders
SET status             = $1,
    updated_at         = now(),
    paid_at            = CASE WHEN $2::boolean THEN coalesce(paid_at, now()) ELSE paid_at END,
    accepted_at        = CASE WHEN $1 = 'accepted' THEN now() ELSE accepted_at END,
    ready_at           = CASE WHEN $1 IN ('ready_for_pickup', 'awaiting_driver') THEN coalesce(ready_at, now()) ELSE ready_at END,
    picked_up_at       = CASE WHEN $1 = 'picked_up' THEN now() ELSE picked_up_at END,
    completed_at       = CASE WHEN $1 IN ('completed', 'delivered') THEN now() ELSE completed_at END,
    cancelled_at       = CASE WHEN $1 = 'cancelled' THEN coalesce(cancelled_at, now()) ELSE cancelled_at END,
    refunded_at        = CASE WHEN $1 = 'refunded' THEN now() ELSE refunded_at END,
    seller_deadline_at = coalesce($3, seller_deadline_at),
    cancel_reason      = CASE WHEN $1 = 'cancelled' THEN $4 ELSE cancel_reason END,
    refund_due_xof     = $5,
    stock_released     = $6
WHERE id = $7 AND status = $8
`

type UpdateStatusParams struct {
	ToStatus         string
	MarkPaid         bool
	SellerDeadlineAt *time.Time
	Reason           string
	RefundDueXof     int64
	StockReleased    bool
	ID               uuid.UUID
	FromStatus       string
}

func (q *Queries) UpdateStatus(ctx context.Context, arg UpdateStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateStatus,
		arg.ToStatus,
		arg.MarkPaid,
		arg.SellerDeadlineAt,
		arg.Reason,
		arg.RefundDueXof,
		arg.StockReleased,
		arg.ID,
		arg.FromStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
